import java.util.*;
import java.io.*;

public class Main {
    static long[][] sortMatrix(long[][] grid) {
        // Write your solution here
        return grid;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int r = (int) in.nval;
        in.nextToken();
        int c = (int) in.nval;
        long[][] grid = new long[r][c];
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                in.nextToken();
                grid[i][j] = (long) in.nval;
            }
        long[][] result = sortMatrix(grid);
        StringBuilder sb = new StringBuilder();
        for (long[] row : result) {
            for (int j = 0; j < row.length; j++) sb.append(row[j]).append(j + 1 < row.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}

